package com.puc.adapters.out.persistence;

import jakarta.persistence.*;
import java.util.UUID;

@Entity @Table(name="piloto") class PilotoJpaEntity { @Id @GeneratedValue UUID id; @Column(nullable=false,unique=true) String codigo; @Column(nullable=false) String nome; protected PilotoJpaEntity(){} PilotoJpaEntity(String c,String n){codigo=c;nome=n;} }
@Entity @Table(name="aeronave") class AeronaveJpaEntity { @Id @GeneratedValue UUID id; @Column(nullable=false,unique=true) String prefixo; @Column(name="velocidade_cruzeiro_kmh",nullable=false) double velocidade; @Column(name="autonomia_nominal_km",nullable=false) double autonomia; @Enumerated(EnumType.STRING) @Column(nullable=false) CategoriaPersistida categoria; @Column(name="empresa_manutencao") String empresa; @Column(name="companhia_aerea") String companhia; @Column(name="capacidade_maxima_passageiros") Integer passageiros; @Column(name="capacidade_maxima_carga_toneladas") Double carga; protected AeronaveJpaEntity(){} }
@Entity @Table(name="aerovia") class AeroviaJpaEntity { @Id @GeneratedValue UUID id; @Column(nullable=false,unique=true) String identificador; @ManyToOne(optional=false) @JoinColumn(name="aeroporto_origem_id") AeroportoJpaEntity origem; @ManyToOne(optional=false) @JoinColumn(name="aeroporto_destino_id") AeroportoJpaEntity destino; @Column(name="distancia_quilometros",nullable=false) double distancia; protected AeroviaJpaEntity(){} }
@Entity @Table(name="plano_voo") class PlanoJpaEntity { @Id @GeneratedValue UUID id; @Column(nullable=false,unique=true) String identificador; @Column(name="partida_prevista",nullable=false) java.time.LocalDateTime partida; @Enumerated(EnumType.STRING) @Column(nullable=false) SituacaoPersistida situacao; protected PlanoJpaEntity(){} }
@Entity @Table(name="trecho") class TrechoJpaEntity { @Id @GeneratedValue UUID id; @Column(name="ordem",nullable=false) int ordem; @Column(name="altitude_pes",nullable=false) int altitude; @Column(nullable=false) java.time.LocalDateTime entrada; @Column java.time.LocalDateTime chegada; @Column(name="operacao_chegada",nullable=false) String operacao; @Column(name="permanencia_minutos",nullable=false) int permanencia; @Column Integer vaga; protected TrechoJpaEntity(){} }
@Entity @Table(name="reserva_aerovia") class ReservaAeroviaJpaEntity { @Id @GeneratedValue UUID id; @Column(name="plano_voo_id",nullable=false) UUID planoId; @Column(name="aerovia_id",nullable=false) UUID aeroviaId; @Column(name="altitude_pes",nullable=false) int altitude; @Column(nullable=false) java.time.LocalDateTime inicio; @Column(nullable=false) java.time.LocalDateTime fim; protected ReservaAeroviaJpaEntity(){} }
@Entity @Table(name="reserva_vaga") class ReservaVagaJpaEntity { @Id @GeneratedValue UUID id; @Column(name="plano_voo_id",nullable=false) UUID planoId; @Column(name="aeroporto_id",nullable=false) UUID aeroportoId; @Column(nullable=false) int vaga; @Column(nullable=false) java.time.LocalDateTime inicio; @Column(nullable=false) java.time.LocalDateTime fim; protected ReservaVagaJpaEntity(){} }
enum CategoriaPersistida { PARTICULAR, COMERCIAL_PASSAGEIROS, COMERCIAL_CARGA }
enum SituacaoPersistida { EM_EDICAO, APROVADO, CANCELADO, ABANDONADO }
